// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.lang.ref.Reference;
import java.lang.ref.WeakReference;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Actual source-cache confound, independent of the experimental memo and outside latency measurement. */
class NativeMemoSourceCacheRetentionDiagnosticTest {

	private static final int MASK = ValuePosition.OBJECT;
	private static final int SHARED_CACHE_CHARACTER_LIMIT = 1_048_576;

	@TempDir
	Path directory;

	@Test
	void decodedSourceCachesOwnOrdinaryValuesButExcludePayloadsAboveTheCharacterLimit() throws IOException {
		Path valuesDirectory = directory.resolve("values");
		long[] ids = seedAndClose(valuesDirectory);
		ValueStore store = new ValueStore(valuesDirectory.toFile(), new LmdbStoreConfig());
		try {
			Observed small = decodeAndObserve(store, ids[0], 1_024, true);
			Observed atLimit = decodeAndObserve(store, ids[1], SHARED_CACHE_CHARACTER_LIMIT, true);
			Observed overLimit = decodeAndObserve(store, ids[2], SHARED_CACHE_CHARACTER_LIMIT + 1, false);
			WeakReference<Object> control = collectionControl();
			for (int attempt = 0; attempt < 24
					&& (!control.refersTo(null) || !overLimit.value.refersTo(null)
							|| !overLimit.payload.refersTo(null)); attempt++) {
				System.gc();
			}
			assertThat(control.refersTo(null)).as("Collection control must clear before interpreting cache roots")
					.isTrue();
			assertThat(small.value.refersTo(null)).as("Source cache strongly owns a decoded ordinary value").isFalse();
			assertThat(small.payload.refersTo(null)).as("Source-owned ordinary payload remains reachable").isFalse();
			assertThat(atLimit.value.refersTo(null)).as("The inclusive character-limit boundary remains cacheable")
					.isFalse();
			assertThat(atLimit.payload.refersTo(null)).as("The inclusive boundary payload remains reachable").isFalse();
			assertThat(overLimit.value.refersTo(null)).as("The oversized decoded value has no source-cache owner")
					.isTrue();
			assertThat(overLimit.payload.refersTo(null)).as("The oversized decoded payload must become collectible")
					.isTrue();
			assertCachedIdentity(store, ids[0], small);
			assertCachedIdentity(store, ids[1], atLimit);
			assertThat(store.cachedValue(ids[2], MASK)).isNull();
		} finally {
			Reference.reachabilityFence(store);
			store.close();
		}
	}

	/** Seeding happens in a separate store/frame so input models cannot own the later decoded representatives. */
	private static long[] seedAndClose(Path directory) throws IOException {
		ValueStore store = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		try {
			int[] lengths = { 1_024, SHARED_CACHE_CHARACTER_LIMIT, SHARED_CACHE_CHARACTER_LIMIT + 1 };
			long[] ids = new long[lengths.length];
			store.startTransaction(true);
			for (int index = 0; index < lengths.length; index++) {
				String prefix = "urn:source-cache-retention:" + lengths[index] + ":";
				String payload = prefix + "x".repeat(lengths[index] - prefix.length());
				ids[index] = store.storeValue(SimpleValueFactory.getInstance().createIRI(payload));
			}
			store.commit();
			return ids;
		} finally {
			store.close();
		}
	}

	/** Only weak observers leave this helper; neither assertions nor locals persist as consumer roots. */
	private static Observed decodeAndObserve(ValueStore store, long id, int characters, boolean expectedCached)
			throws IOException {
		LmdbValue value = store.getLazyValue(id, MASK);
		String payload = value.stringValue();
		assertThat(payload.length()).isEqualTo(characters);
		assertThat(value.retainedLexicalLength()).isEqualTo(characters);
		if (expectedCached) {
			assertThat(store.cachedValue(id, MASK)).isSameAs(value);
		} else {
			assertThat(store.cachedValue(id, MASK)).as("Oversized completion must not enter either shared value cache")
					.isNull();
		}
		return new Observed(new WeakReference<>(value), new WeakReference<>(payload));
	}

	private static void assertCachedIdentity(ValueStore store, long id, Observed observed) {
		LmdbValue cached = store.cachedValue(id, MASK);
		assertThat(cached).isNotNull();
		assertThat(observed.value.refersTo(cached)).as("The same decoded representative remains source-owned")
				.isTrue();
	}

	private static WeakReference<Object> collectionControl() {
		return new WeakReference<>(new Object());
	}

	private record Observed(WeakReference<LmdbValue> value, WeakReference<String> payload) {
	}
}
